"""Render a text template from the step's named inputs.

Templates use the same placeholders as prompt templates: `{name}` is
replaced by the input called `name`, and `{{` and `}}` are literal braces. A
string is inserted as it is, and any other value as compact JSON, exactly as
a prompt renders it. Only plain names are allowed: no fields, indexes,
conversions or format specifications; select nested values with
`json_select` first. Inputs the template does not use are ignored.
"""

import json
import string
import sys

TOOL = "render_template"


def fail(status, message):
    sys.stderr.buffer.write(message.encode("utf-8"))
    sys.exit(status)


def parse(template):
    try:
        pieces = list(string.Formatter().parse(template))
    except ValueError as error:
        fail(2, f"{TOOL} could not read the template: {error}.")

    for _, name, spec, conversion in pieces:
        if name is None:
            continue

        if not name.isidentifier() or spec or conversion is not None:
            shown = "{" + name + ("!" + conversion if conversion else "")
            shown = shown + (":" + spec if spec else "") + "}"
            fail(2, f"{TOOL} allows only plain {{name}} placeholders; {shown} is not one.")

    return pieces


def render_value(value):
    if isinstance(value, str):
        return value

    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


inputs = json.loads(sys.stdin.buffer.read().decode("utf-8"))

if "template" not in inputs:
    fail(2, f"{TOOL} needs the input 'template'.")

template = inputs.pop("template")

if not isinstance(template, str):
    fail(2, f"{TOOL} needs 'template' to be a string.")

parts = []

for literal, name, _, _ in parse(template):
    parts.append(literal)

    if name is None:
        continue

    if name == "template":
        fail(2, f"{TOOL} reserves the name 'template' for the template itself.")

    if name not in inputs:
        fail(2, f"{TOOL} has no value for {{{name}}}.")

    parts.append(render_value(inputs[name]))

sys.stdout.buffer.write(json.dumps({"text": "".join(parts)}, ensure_ascii=False).encode("utf-8"))
